export const optimizationRawRules = Object.freeze(Object.fromEntries(
  Object.entries(rawCounterGroups).flatMap(([optimization, counters]) =>
    counters.map(([id, unit]) => [id, Object.freeze({optimization, unit})])),
));

// For unmeasured entries, unit describes the kind of site the mechanism acts on.
const entry = (id, label, category, scope, unit, description, rules = []) =>
  Object.freeze({id, label, category, scope, unit, description, rules: Object.freeze(rules),
    rawRules: Object.freeze((rawCounterGroups[id] ?? []).map(([rule]) => rule))});

